mapper.select:
SELECT COUNT(*)
FROM erp_bookstore_reservation r
JOIN erp_bookstore_slot_instance si ON si.slot_instance_id = r.slot_instance_id
WHERE r.student_id = #{studentId}
  AND si.service_date = #{serviceDate}
  AND r.status <> 'CANCELED'

SELECT COUNT(*)
FROM erp_bookstore_reservation r
JOIN erp_bookstore_slot_instance si ON si.slot_instance_id = r.slot_instance_id
WHERE r.student_id = #{studentId}
  AND si.service_date BETWEEN #{monthStart} AND #{monthEnd}
  AND r.status <> 'CANCELED'

SELECT student_id
FROM erp_student WITH (UPDLOCK, HOLDLOCK, ROWLOCK)
WHERE student_id = #{studentId}

SELECT COUNT(*)
FROM erp_bookstore_reservation r
JOIN erp_bookstore_slot_instance si ON si.slot_instance_id = r.slot_instance_id
WHERE r.student_id = #{studentId}
  AND si.service_date = #{serviceDate}
  AND r.status = 'ATTENDED'

mapper.update:
UPDATE erp_bookstore_reservation
SET status = 'CANCELED',
    canceled_at = DATEADD(HOUR, 9, GETUTCDATE()),
    cancel_reason = #{reason}
WHERE reservation_id = #{reservationId}
  AND student_id = #{studentId}
  AND status = 'RESERVED'

mapper.select:
SELECT slot_instance_id
FROM erp_bookstore_reservation
WHERE reservation_id = #{reservationId}
  AND student_id = #{studentId}

mapper.update:
UPDATE erp_bookstore_reservation
SET status = #{toStatus}
WHERE reservation_id = #{reservationId}
  AND status = #{fromStatus}
